  if (image != (MagickCore::Image *) NULL) {
    if (image->next != (MagickCore::Image *) NULL) {
      MagickCore::Image *next;

      while (image->next != (MagickCore::Image *) NULL) {
        next = image->next;
        image->next = next->next;
        DestroyImage(next);
      }
    }

    ReplaceImage(&image, image);
  }

  if (exceptionInfo != (MagickCore::ExceptionInfo *) NULL) {
    if (image == (MagickCore::Image *) NULL) {
      DestroyExceptionInfo(exceptionInfo);
      (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "NullImage", "image == NULL");
